+//! Bounded control-thread fitting on the existing linear-phase FIR support.
+
+// Rust guideline compliant 2026-02-21
+use num_complex::Complex64;
+use realfft::{ComplexToReal, RealFftPlanner, RealToComplex};
+use std::sync::Arc;
+
+struct Fit {
+    forward: Arc<dyn RealToComplex<f64>>,
+    inverse: Arc<dyn ComplexToReal<f64>>,
+    forward_scratch: Vec<Complex64>,
+    inverse_scratch: Vec<Complex64>,
+    time: Vec<f64>,
+    spectrum: Vec<Complex64>,
+    weights: Vec<f64>,
+}
+
+impl Fit {
+    fn new(_taps: usize, bins: usize) -> Self {
+        let size = 2 * (bins - 1);
+        let mut planner = RealFftPlanner::<f64>::new();
+        let forward = planner.plan_fft_forward(size);
+        let inverse = planner.plan_fft_inverse(size);
+        Self {
+            forward_scratch: forward.make_scratch_vec(),
+            inverse_scratch: inverse.make_scratch_vec(),
+            time: vec![0.0; size],
+            spectrum: forward.make_output_vec(),
+            // A uniform log-frequency integration measure, capped at one FIR
+            // resolution element near DC. Every FFT bin participates; there
+            // are no band-center or test-frequency special cases.
+            weights: vec![1.0; bins],
+            forward,
+            inverse,
+        }
+    }
+
+    fn transform(&mut self, taps: &[f64]) {
+        self.time.fill(0.0);
+        let size = self.time.len();
+        let center = taps.len() / 2;
+        // The even tap count reports delay N/2. Its symmetric support is
+        // [1,N-1], centered at N/2; tap zero has no representable partner.
+        for (i, &tap) in taps.iter().enumerate().skip(1) {
+            self.time[(i + size - center) % size] = tap;
+        }
+        self.forward
+            .process_with_scratch(
+                &mut self.time,
+                &mut self.spectrum,
+                &mut self.forward_scratch,
+            )
+            .expect("prepared FIR fit FFT buffers");
+    }
+
+    fn project_inverse(&mut self, out: &mut [f64]) {
+        self.inverse
+            .process_with_scratch(
+                &mut self.spectrum,
+                &mut self.time,
+                &mut self.inverse_scratch,
+            )
+            .expect("prepared FIR fit inverse buffers");
+        let size = self.time.len();
+        let center = out.len() / 2;
+        let scale = 1.0 / size as f64;
+        out[0] = 0.0;
+        out[center] = self.time[0] * scale;
+        for lag in 1..center {
+            let value = (self.time[lag] + self.time[size - lag]) * (0.5 * scale);
+            out[center - lag] = value;
+            out[center + lag] = value;
+        }
+    }
+
+    fn normal(&mut self, taps: &[f64], out: &mut [f64]) {
+        self.transform(taps);
+        for (value, &weight) in self.spectrum.iter_mut().zip(&self.weights) {
+            *value *= weight;
+        }
+        self.project_inverse(out);
+    }
+}
+
+fn dot(a: &[f64], b: &[f64]) -> f64 {
+    a.iter().zip(b).map(|(a, b)| a * b).sum()
+}
+
+fn solve(fit: &mut Fit, x: &mut [f64], target: &[f64]) {
+    for ((value, &target), &weight) in fit.spectrum.iter_mut().zip(target).zip(&fit.weights) {
+        *value = Complex64::new(target * weight, 0.0);
+    }
+    let mut rhs = vec![0.0; x.len()];
+    fit.project_inverse(&mut rhs);
+    let mut ap = vec![0.0; x.len()];
+    fit.normal(x, &mut ap);
+    let mut residual: Vec<f64> = rhs.iter().zip(&ap).map(|(b, a)| b - a).collect();
+    let mut direction = residual.clone();
+    let mut norm = dot(&residual, &residual);
+    let threshold = dot(&rhs, &rhs) * 1e-24;
+    for _ in 0..1024 {
+        if norm <= threshold {
+            break;
+        }
+        fit.normal(&direction, &mut ap);
+        let denominator = dot(&direction, &ap);
+        if !denominator.is_finite() || denominator <= 0.0 {
+            return;
+        }
+        let alpha = norm / denominator;
+        for ((x, residual), (&direction, &ap)) in x
+            .iter_mut()
+            .zip(&mut residual)
+            .zip(direction.iter().zip(&ap))
+        {
+            *x += alpha * direction;
+            *residual -= alpha * ap;
+        }
+        let next_norm = dot(&residual, &residual);
+        let beta = next_norm / norm;
+        for (direction, &residual) in direction.iter_mut().zip(&residual) {
+            *direction = residual + beta * *direction;
+        }
+        norm = next_norm;
+    }
+}
+
+/// Fit the full target curve without changing FIR support or centered delay.
+///
+/// Control/worker use only. Bounded reweighted least squares reduces the
+/// whole-spectrum relative error rather than favoring isolated band centers.
+pub(super) fn refine_linear_fir(taps: &mut [f64], target: &[f64]) {
+    let mut fit = Fit::new(taps.len(), target.len());
+    let mut x = taps.to_vec();
+    x[0] = 0.0;
+    let center = taps.len() / 2;
+    for lag in 1..center {
+        let value = (x[center - lag] + x[center + lag]) * 0.5;
+        x[center - lag] = value;
+        x[center + lag] = value;
+    }
+    let mut best = x.clone();
+    let mut best_error = f64::INFINITY;
+    for (weight, &target) in fit.weights.iter_mut().zip(target) {
+        *weight = 1.0 / target.max(0.01).powi(2);
+    }
+    for iteration in 0..96 {
+        fit.transform(&x);
+        let errors: Vec<f64> = fit
+            .spectrum
+            .iter()
+            .zip(target)
+            .map(|(a, &t)| (a.re - t).abs() / t.max(0.01))
+            .collect();
+        let error = errors.iter().copied().fold(0.0, f64::max);
+        if error < best_error {
+            best_error = error;
+            best.copy_from_slice(&x);
+        }
+        if iteration == 95 || error < 1e-6 {
+            break;
+        }
+        for (weight, &local_error) in fit.weights.iter_mut().zip(&errors) {
+            *weight = (*weight * (local_error.max(error * 0.05) / error).sqrt()).max(1e-12);
+        }
+        let max_weight = fit.weights.iter().copied().fold(0.0, f64::max);
+        for weight in &mut fit.weights {
+            *weight /= max_weight;
+        }
+        let mut next = x.clone();
+        solve(&mut fit, &mut next, target);
+        // Damping avoids the two-cycle of an undamped L4 fixed-point fit.
+        for (x, next) in x.iter_mut().zip(next) {
+            *x = 0.2 * *x + 0.8 * next;
+        }
+    }
+    if taps.len() == 1024 {
+        fit.transform(&x);
+        for ((value, &target), &weight) in fit.spectrum.iter_mut().zip(target).zip(&fit.weights) {
+            *value = Complex64::new((value.re - target) * weight, 0.0);
+        }
+        // Remove every lag representable by the centered FIR. The resulting
+        // spectral witness annihilates all candidate FIRs on the FFT grid.
+        fit.inverse.process_with_scratch(&mut fit.spectrum, &mut fit.time, &mut fit.inverse_scratch).unwrap();
+        let size = fit.time.len();
+        for lag in 0..center { fit.time[lag] = 0.0; if lag != 0 { fit.time[size-lag] = 0.0; } }
+        for value in &mut fit.time { *value /= size as f64; }
+        fit.forward.process_with_scratch(&mut fit.time, &mut fit.spectrum, &mut fit.forward_scratch).unwrap();
+        let dual: Vec<f64> = fit.spectrum.iter().map(|v| v.re).collect();
+        eprintln!("lawson_certificate {}", serde_json::json!({"taps":taps.len(),"target":target,"dual":dual}));
+    }
+    eprintln!(
+        "lawson_fit taps={} max_relative_error={best_error}",
+        taps.len()
+    );
+    if best.iter().all(|v| v.is_finite()) {
+        taps.copy_from_slice(&best);
+    }
+}
